INSERT INTO tracks(id,project_id,slug,title,created_by,created_at,updated_at) SELECT ('00000000-0000-0000-0000-'||lpad(i::text,12,'0'))::uuid,'00000000-0000-0000-0000-000000000010','track-'||i,'Track','00000000-0000-0000-0000-000000000001','2001-01-01Z','2001-01-01Z' FROM generate_series(3,4)i;
INSERT INTO hypotheses(id,project_id,number,track_id,state,title,created_by_user,revision,approved_revision,approved_at,created_at,updated_at) SELECT ('00000000-0000-0000-0000-'||lpad((1000+n)::text,12,'0'))::uuid,'00000000-0000-0000-0000-000000000010',n,('00000000-0000-0000-0000-'||lpad(CASE WHEN n=1 THEN 3 ELSE 4 END::text,12,'0'))::uuid,'queued','Claim fixture','00000000-0000-0000-0000-000000000001',1,1,'2001-01-01Z','2001-01-01Z','2001-01-01Z' FROM generate_series(1,2)n;
INSERT INTO hypothesis_revisions(hypothesis_id,revision,content,science_revision,author_user,via_channel,created_at) SELECT id,1,'{"title":"Claim fixture","project_fields":{"unicode":"é😀","wide":123456789012345678901234567890},"control":null}',1,'00000000-0000-0000-0000-000000000001','api','2001-01-01Z' FROM hypotheses;
